    def fit(self, ds):
        opt = torch.optim.Adam(self.parameters())
        crit = nn.CrossEntropyLoss()
        loader = DataLoader(ds, batch_size=8, shuffle=True)
        for xb, yb in loader:
            opt.zero_grad()
            loss = crit(self.net(xb), yb)
            loss.backward()
            opt.step()
        return self
